import Foundation

// MARK: - User Profile

struct UserProfile: Codable, Equatable {
    var surname: String
    var gender: Gender
    var height: Int?       // cm
    var birthYear: Int?    // 出生年份

    enum Gender: String, Codable, CaseIterable {
        case male, female
        var honorific: String { self == .male ? "先生" : "女士" }
    }

    var displayName: String { "\(surname)\(gender.honorific)" }

    var age: Int? {
        guard let birthYear else { return nil }
        let currentYear = Calendar.current.component(.year, from: Date())
        return currentYear - birthYear
    }
}

// MARK: - Heart Rate Record

struct HeartRateRecord: Codable, Identifiable, Equatable {
    var id = UUID()
    let date: Date
    let averageHR: Int
    let maxHR: Int
    let minHR: Int
}

// MARK: - Scale Record

struct ScaleRecord: Codable, Identifiable, Equatable {
    var id = UUID()
    let date: Date
    let weight: Double
    let bmi: Double
    let bodyFat: Double
}

